<?php
require_once __DIR__.'/../../includes/accounting_ui.php';
$studentId=(int)($_GET['student']??$_GET['student_id']??0);$customer=trim($_GET['customer']??'');
acHandle(fn()=>$ac->recordPayment($_POST),'receipt');
$methods=$ac->rows('SELECT id,name FROM ac_methods WHERE school_id=? AND is_active=1 ORDER BY id',[$school]);$invoices=$ac->rows("SELECT * FROM ac_invoices WHERE school_id=? AND status='issued'".($studentId?' AND student_id=?':($customer!==''?' AND student_id IS NULL AND customer_name=?':' AND 1=0')).' ORDER BY due_date,id',[$school,...($studentId?[$studentId]:($customer!==''?[$customer]:[]))]);$invoices=array_values(array_filter($invoices,fn($i)=>$ac->invoiceBalance((int)$i['id'])>0));ob_start();
?>
<form method="get" class="card card-body mb-3"><?php acStudentPicker($studentId);acInput('customer','Or external invoice customer',$customer,'text',false); ?><button class="btn btn-secondary align-self-start">Load unpaid invoices</button></form>
<?php if($studentId): ?><div class="alert alert-info">Account outstanding <?= acMoney($ac->outstanding($studentId)) ?> · Available advance <?= acMoney($ac->advanceBalance($studentId)) ?>. <a href="<?= acUrl('student',['student'=>$studentId]) ?>">View account</a></div><?php endif; ?>
<?php if($ac->can('payment')): ?><?php acForm('payment','Collect confirmed payment'); ?><input type="hidden" name="student_id" value="<?= $studentId?:'' ?>"><input type="hidden" name="customer_name" value="<?= sanitize($customer) ?>"><div class="row"><div class="col-md-6"><?php acInput('payment_date','Payment date',date('Y-m-d'),'date');acInput('amount','Amount received (NPR)','0.00','number');acSelect('method_id','Payment method',$methods,$methods[0]['id']??''); ?></div><div class="col-md-6"><?php acInput('reference','Transaction reference','','text',false);acInput('remarks','Remarks','','text',false); ?><label class="mb-3"><input type="checkbox" name="externally_confirmed" value="1"> I verified this bank/digital payment externally.</label><div class="alert alert-warning">Selecting eSewa, Khalti, ConnectIPS or a bank method does not charge anyone or verify a gateway payment.</div></div></div><div class="table-responsive"><table class="table"><thead><tr><th>Invoice</th><th>Due date</th><th>Outstanding</th><th>Allocate NPR</th></tr></thead><tbody><?php foreach($invoices as $i): ?><tr><td><a href="<?= acUrl('invoice',['id'=>$i['id']]) ?>"><?= sanitize($i['number']) ?></a></td><td><?= sanitize(schoolDateLabel($i['due_date'],'both','ymd')) ?></td><td><?= acMoney($ac->invoiceBalance((int)$i['id'])) ?></td><td><input type="number" step="0.01" min="0" max="<?= acAmount($ac->invoiceBalance((int)$i['id'])) ?>" name="allocations[<?= $i['id'] ?>]" value="0.00" class="form-control" aria-label="Payment allocated to <?= sanitize($i['number']) ?>"></td></tr><?php endforeach; ?><?php if(!$invoices): ?><tr><td colspan="4">Choose a student/customer and load their invoices, or explicitly record a student advance.</td></tr><?php endif; ?></tbody></table></div><label><input type="checkbox" name="allow_advance" value="1"> Record any unallocated amount as student advance (liability, not fee income).</label><?php acSubmit('Post payment & open receipt'); ?><?php endif; ?>
<div class="card card-body mt-4 table-responsive"><h4>Payment history</h4><table class="table"><thead><tr><th>Receipt</th><th>Customer</th><th>Date</th><th>Amount</th><th>Status</th></tr></thead><tbody><?php foreach($ac->rows('SELECT * FROM ac_payments WHERE school_id=?'.($studentId?' AND student_id=?':'').' ORDER BY id DESC LIMIT 100',[$school,...($studentId?[$studentId]:[])]) as $r): ?><tr><td><a href="<?= acUrl('receipt',['id'=>$r['id']]) ?>"><?= sanitize($r['number']) ?></a></td><td><?= sanitize($r['customer_name']) ?></td><td><?= sanitize(schoolDateLabel($r['payment_date'],'both','ymd')) ?></td><td><?= acMoney((int)$r['amount_minor']) ?></td><td><?= sanitize($r['status']) ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php acRender('Payment collection',ob_get_clean());
